#include <stdio.h>
#include <string.h>

int uniqueLetterString(char *s) {
    int last[26], prev[26];
    for (int i = 0; i < 26; ++i) {
        last[i] = -1;
        prev[i] = -1;
    }

    long long result = 0;
    int n = (int)strlen(s);

    for (int i = 0; i < n; ++i) {
        int x = s[i] - 'A';
        result += (long long)(i - prev[x]) * (prev[x] - last[x]);
        last[x] = prev[x];
        prev[x] = i;
    }

    for (int x = 0; x < 26; ++x) {
        result += (long long)(n - prev[x]) * (prev[x] - last[x]);
    }

    return (int)result;
}

int main(void) {
    char line[1000005];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    int len = (int)strlen(line);
    while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
        line[--len] = '\0';
    }

    char s[100001];
    int stringLen = len - 4;
    memcpy(s, line + 2, stringLen);
    s[stringLen] = '\0';

    printf("%d\n", uniqueLetterString(s));
    return 0;
}

