class Solution {
public:
    int uniqueLetterString(string s) {
        int last[26], prev[26];
        fill(last, last + 26, -1);
        fill(prev, prev + 26, -1);

        long long result = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            int x = s[i] - 'A';
            result += 1LL * (i - prev[x]) * (prev[x] - last[x]);
            last[x] = prev[x];
            prev[x] = i;
        }

        int n = (int)s.size();
        for (int x = 0; x < 26; ++x) {
            result += 1LL * (n - prev[x]) * (prev[x] - last[x]);
        }

