import java.io.*;
import java.util.*;

class Solution {
    public int uniqueLetterString(String s) {
        int[] last = new int[26];
        int[] prev = new int[26];
        Arrays.fill(last, -1);
        Arrays.fill(prev, -1);

        long result = 0;
        for (int i = 0; i < s.length(); i++) {
            int x = s.charAt(i) - 'A';
            result += (long) (i - prev[x]) * (prev[x] - last[x]);
            last[x] = prev[x];
            prev[x] = i;
        }

        int n = s.length();
        for (int x = 0; x < 26; x++) {
            result += (long) (n - prev[x]) * (prev[x] - last[x]);
        }

        return (int) result;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        String s = line.substring(2, line.length() - 2);
        System.out.println(new Solution().uniqueLetterString(s));
    }
}

